-- The press the participant reads was written into a React component, so a new
-- scenario inherited an ANPD consultation and a competitor announcement that
-- had nothing to do with it. It becomes scenario data, like the cast and the
-- artifacts before it.
--
-- Calls get an explicit switch. Voice is billed per minute of audio rather than
-- per token, so the queue built for turns does not govern it at all -- leaving
-- it always on would be spending nobody is watching.

alter table public.challenge_scenarios add column if not exists news jsonb not null default '[]';
alter table public.challenge_scenarios add column if not exists calls_enabled boolean not null default false;

update public.challenge_scenarios
set news = '[{"id": "news-anpd", "source": "Portal RegTech", "at": 545, "tag": "Regulação", "headline": "ANPD abre consulta sobre uso de dados pessoais em treinamento de IA", "summary": "A autoridade quer ouvir empresas sobre bases legais para uso de dados de clientes em sistemas de IA generativa. Prazo de contribuição termina em 30 dias.", "article": "A Autoridade Nacional de Proteção de Dados abriu consulta pública sobre o uso de dados pessoais no treinamento e na operação de sistemas de inteligência artificial generativa.\n\nO documento em consulta trata especificamente de ambientes de teste e homologação, hoje um ponto cinzento: muitas empresas replicam bases de produção para validar modelos sem registrar essa etapa em seus inventários de tratamento.\n\n\"O ambiente de homologação não é um lugar fora da lei\", afirmou uma das técnicas envolvidas na redação. \"Se há dado pessoal real ali, há tratamento, e há responsabilidade.\"\n\nA consulta também pede subsídios sobre transferência internacional quando o fornecedor do modelo opera fora do país — cenário comum entre empresas que contratam APIs de terceiros.\n\nEspecialistas ouvidos avaliam que a orientação final deve exigir registro formal da avaliação de impacto antes da entrada em produção, e não depois."}, {"id": "news-incidente", "source": "Tecnologia & Negócios", "at": 520, "tag": "Mercado", "headline": "Empresa do setor financeiro suspende assistente de IA após exposição de dados", "summary": "O sistema retornava trechos de atendimentos de outros clientes. A companhia afirma que o piloto havia sido aprovado internamente.", "article": "Uma instituição financeira de médio porte suspendeu nesta semana o assistente de IA que atendia seus canais digitais, depois que clientes relataram receber respostas contendo trechos de atendimentos de terceiros.\n\nSegundo a apuração interna, o conjunto de dados usado para ajustar o modelo continha transcrições completas de atendimento, incluindo campos que não haviam sido mapeados na avaliação inicial.\n\nA companhia informou que o piloto passou por aprovação interna e que os controles declarados pelo fornecedor foram considerados suficientes à época.\n\nO caso reacendeu a discussão sobre a diferença entre a segurança declarada por um fornecedor e a validação independente feita por quem responde pelo risco.\n\n\"Ninguém foi negligente de forma óbvia\", disse um consultor da área. \"O que faltou foi alguém perguntar qual recorte exato dos dados entrou, e ter a resposta por escrito.\""}, {"id": "news-concorrente", "source": "Mercado Digital", "at": 492, "tag": "Concorrência", "headline": "Concorrente anuncia assistente de IA em produção e ações sobem", "summary": "O anúncio pressiona companhias do setor que ainda tratam seus projetos como piloto.", "article": "Um dos principais concorrentes do setor anunciou a entrada em produção de seu assistente de IA para atendimento, com previsão de cobertura total dos canais até o fim do trimestre.\n\nO mercado reagiu bem: as ações da companhia subiram no pregão seguinte ao anúncio.\n\nAnalistas apontam, porém, que o comunicado não detalha quais dados alimentam o sistema nem se houve avaliação independente de privacidade — informação que passou a ser cobrada por investidores institucionais.\n\nPara empresas que ainda tratam seus projetos como piloto, o anúncio cria uma pressão de calendário que nem sempre corresponde a uma pressão técnica."}]'::jsonb
where key = 'atlas' and (news is null or news = '[]'::jsonb);
